html:
{%- set r = get_report_context(doc) -%}
{%- set brand = get_brand(True) -%}
<style>
.iamr{font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;color:{{ brand.ink }};font-size:10.5px;line-height:1.4}
.iamr h1{font-size:22px;margin:0 0 4px;font-weight:600}
.iamr h2{font-size:14px;margin:16px 0 6px;font-weight:600;border-bottom:1px solid #D7E0E5;padding-bottom:4px}
.iamr h2 .k{color:{{ brand.primary }};font-size:11px;font-weight:500;margin-right:6px}
.iamr .eyebrow{font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:{{ brand.primary }};font-weight:600}
.iamr .muted{color:#586976}
.iamr table.t{width:100%;border-collapse:collapse;margin-top:4px}
.iamr table.t th{font-size:8.5px;letter-spacing:.06em;text-transform:uppercase;color:#586976;text-align:left;background:#F3F6F7;padding:5px 7px;border-bottom:1px solid #D7E0E5}
.iamr table.t td{padding:4px 7px;border-bottom:1px solid #E6ECEF;vertical-align:top}
.iamr table.t tr{page-break-inside:avoid}
.iamr .num{text-align:right;white-space:nowrap}
.iamr .pill{display:inline-block;font-size:10px;font-weight:600;padding:1px 8px;border-radius:9px;border:1px solid}
.iamr .big{font-size:48px;font-weight:600;line-height:1}
.iamr .big small{font-size:20px}
.iamr .note{border-left:3px solid #BF530B;background:#FFF6E0;padding:8px 10px;margin-top:8px}
.iamr .head{border-bottom:2px solid {{ brand.ink }};padding-bottom:10px;margin-bottom:6px}
.iamr .sec{page-break-inside:avoid}
.iamr .brandline{height:4px;background:{{ brand.primary }};margin:0 0 14px}
</style>
<div class="iamr">
 <div class="brandline"></div>
 <table style="width:100%" class="head"><tr>
  <td style="vertical-align:bottom">
   <img src="{{ brand.images.logo }}" alt="AlphaX" style="height:46px;width:auto;margin-bottom:8px">
   <div class="eyebrow">{{ brand.product }} · {{ _("Results report") }}</div>
   <h1>{{ _("Internal Audit Function Maturity Assessment") }}</h1>
   <div class="muted" style="font-size:13px">{{ r.entity|e }}</div>
  </td>
  <td style="vertical-align:bottom;width:260px">
   <table style="font-size:10.5px">
    <tr><td class="muted" style="padding-right:10px">{{ _("Reference") }}</td><td>{{ r.name|e }}</td></tr>
    <tr><td class="muted" style="padding-right:10px">{{ _("Assessment date") }}</td><td>{{ r.date|e }}</td></tr>
    <tr><td class="muted" style="padding-right:10px">{{ _("Assessed by") }}</td><td>{{ r.respondent|e }}{% if r.job_title %}, {{ r.job_title|e }}{% endif %}</td></tr>
    {% if r.respondent_role %}<tr><td class="muted" style="padding-right:10px">{{ _("Perspective") }}</td><td>{{ r.respondent_role|e }}</td></tr>{% endif %}
    <tr><td class="muted" style="padding-right:10px">{{ _("Framework") }}</td><td>{{ _("IIA Global Internal Audit Standards") }}</td></tr>
    <tr><td class="muted" style="padding-right:10px">{{ _("Questions") }}</td><td>{{ r.question_count|e }} {{ _("across") }} {{ r.section_count|e }} {{ _("sections") }}</td></tr>
   </table>
  </td></tr></table>

 <div class="sec">
 <h2><span class="k">01</span>{{ _("Executive summary") }}</h2>
 <table style="width:100%"><tr>
  <td style="width:190px;vertical-align:top">
   <div class="big">{{ "%g"|format(r.overall) }}<small>%</small></div>
   <div style="margin-top:6px"><span class="pill" style="color:{{ r.level_color|e }};border-color:{{ r.level_color|e }}">{{ r.level|e }}</span></div>
   <div class="muted" style="margin-top:6px;font-size:10.5px">{{ "%g"|format(r.points) }} {{ _("of") }} {{ "%g"|format(r.max_points) }} {{ _("points") }}</div>
  </td>
  <td style="vertical-align:top">
   <p style="margin:0 0 6px">{{ r.interpretation|e }}</p>
   {% if r.strongest %}<p class="muted" style="margin:0 0 6px">{{ _("Strongest section") }}: <b style="color:{{ brand.ink }}">{{ r.strongest.title|e }}</b> ({{ "%g"|format(r.strongest.pct) }}%).
   {{ _("Weakest section") }}: <b style="color:{{ brand.ink }}">{{ r.weakest.title|e }}</b> ({{ "%g"|format(r.weakest.pct) }}%).
   {{ r.findings_count|e }} {{ _("findings raised") }}, {{ r.immediate_count|e }} {{ _("requiring immediate action") }}.{% if r.na_count %} {{ r.na_count|e }} {{ _("question(s) marked not applicable") }}.{% endif %}</p>{% endif %}
   {%- set mk = [[r.overall, 0.5]|max, 99.5]|min -%}
   <table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:10px"><tr>
    <td style="width:{{ mk }}%;padding:0;height:10px"></td>
    <td style="padding:0;font-size:10px;line-height:10px;color:{{ brand.ink }}"><span style="position:relative;left:-4px">&#9660;</span></td>
   </tr></table>
   <table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:1px"><tr>
    {% for b in r.scale %}<td style="width:{{ b.width|e }}%;height:8px;line-height:8px;font-size:1px;background:{{ b.color|e }};padding:0">&nbsp;</td>{% endfor %}
   </tr><tr>
    {% for b in r.scale %}<td style="font-size:8.5px;color:#586976;padding:3px 0 0">{{ "%g"|format(b.from) }}% {{ b.level|e }}</td>{% endfor %}
   </tr></table>
   {% if r.gating_note %}<div class="note">{{ r.gating_note|e }}</div>{% endif %}
  </td></tr></table>
 </div>

 <div>
 <h2><span class="k">02</span>{{ _("Results by section") }}</h2>
 <div style="text-align:center">{{ section_bar_svg(r) }}</div>
 <table class="t">
  <thead><tr><th>#</th><th>{{ _("Section") }}</th><th class="num">{{ _("Points") }}</th><th class="num">{{ _("Score") }}</th><th>{{ _("Maturity") }}</th></tr></thead>
  <tbody>
  {% for s in r.sections %}
   <tr><td>{{ loop.index }}</td><td>{{ s.title|e }}</td><td class="num">{{ "%g"|format(s.points) }} / {{ "%g"|format(s.max_points) }}</td><td class="num">{{ "%g"|format(s.pct) }}%</td>
   <td><span class="pill" style="color:{{ s.color|e }};border-color:{{ s.color|e }}">{{ s.level|e }}</span></td></tr>
  {% endfor %}
   <tr><td></td><td><b>{{ _("Overall") }}</b></td><td class="num"><b>{{ "%g"|format(r.points) }} / {{ "%g"|format(r.max_points) }}</b></td><td class="num"><b>{{ "%g"|format(r.overall) }}%</b></td>
   <td><span class="pill" style="color:{{ r.level_color|e }};border-color:{{ r.level_color|e }}">{{ r.level|e }}</span></td></tr>
  </tbody></table>
 </div>

 <h2><span class="k">03</span>{{ _("Key findings") }}</h2>
 {% if r.findings %}
 <table class="t"><thead><tr><th style="width:42px">Q#</th><th>{{ _("Area") }}</th><th style="width:70px">{{ _("Answer") }}</th><th>{{ _("Current practice") }}</th><th style="width:70px">{{ _("Priority") }}</th></tr></thead><tbody>
 {% for f in r.findings %}
  <tr><td>{{ f.code|e }}</td><td><b>{{ f.label|e }}</b><div class="muted" style="font-size:10px">{{ f.section_title|e }}</div></td><td>{{ f.answer|e }} · {{ f.answer_level|e }}</td><td>{{ f.statement|e }}{% if f.comment %}<div class="muted" style="font-size:10px;margin-top:3px">{{ _("Comment") }}: {{ f.comment|e }}</div>{% endif %}</td>
  <td style="color:{{ '#B42318' if f.priority == 'Immediate' else '#BF530B' }};font-weight:600">{{ f.priority|e }}</td></tr>
 {% endfor %}</tbody></table>
 {% else %}<p class="muted">{{ _("No findings: every question was answered at level C or above.") }}</p>{% endif %}

 <h2><span class="k">04</span>{{ _("Improvement roadmap") }}</h2>
 {% if r.actions %}
 <table class="t"><thead><tr><th style="width:42px">Q#</th><th>{{ _("Area") }}</th><th>{{ _("Target practice (next level)") }}</th><th style="width:110px">{{ _("Owner") }}</th><th style="width:80px">{{ _("Timeframe") }}</th></tr></thead><tbody>
 {% for a in r.actions %}
  <tr><td>{{ a.code|e }}</td><td><b>{{ a.label|e }}</b><div class="muted" style="font-size:10px">{{ a.answer|e }} → {{ a.target|e }} ({{ a.target_level|e }})</div></td><td>{{ a.next_statement|e }}</td><td>{{ a.owner|e }}</td>
  <td><span style="color:{{ {'Immediate':'#B42318','High':'#BF530B','Medium':'#9A6F00'}.get(a.priority, '#2D7A33') }};font-weight:600">{{ a.priority|e }}</span><div class="muted" style="font-size:10px">{{ a.timeframe|e }}</div></td></tr>
 {% endfor %}</tbody></table>
 {% else %}<p class="muted">{{ _("No improvement actions required.") }}</p>{% endif %}

 <h2><span class="k">05</span>{{ _("Detailed responses") }}</h2>
 <table class="t"><thead><tr><th style="width:42px">Q#</th><th>{{ _("Question") }}</th><th style="width:85px">{{ _("Answer") }}</th><th class="num" style="width:45px">{{ _("Pts") }}</th></tr></thead><tbody>
 {% for a in r.answers %}
  <tr><td>{{ a.code|e }}</td><td>{{ a.question|e }}<div class="muted" style="font-size:10px;margin-top:2px">{{ a.statement|e }}</div>{% if a.comment %}<div style="font-size:10px;margin-top:2px"><i>{{ _("Evidence / comment") }}:</i> {{ a.comment|e }}</div>{% endif %}</td>
  <td>{{ a.answer|e }}{% if a.answer_level %} · {{ a.answer_level|e }}{% endif %}</td><td class="num">{{ "%g"|format(a.points) if a.answer != "N/A" else "–" }}</td></tr>
 {% endfor %}</tbody></table>

 {% if r.review_status and r.review_status != "Pending Review" %}
 <h2><span class="k">06</span>{{ _("Review") }}</h2>
 <p><b>{{ r.review_status|e }}</b>{% if r.reviewer_comments %} – {{ r.reviewer_comments|e }}{% endif %}</p>
 {% endif %}

 <h2><span class="k">{{ "07" if r.review_status and r.review_status != "Pending Review" else "06" }}</span>{{ _("Scoring method") }}</h2>
 <p class="muted" style="font-size:10.5px">{{ _("Answers score") }} A = {{ "%g"|format(r.points_map.A) }}, B = {{ "%g"|format(r.points_map.B) }}, C = {{ "%g"|format(r.points_map.C) }}, D = {{ "%g"|format(r.points_map.D) }} {{ _("points") }}.
 {{ _("Section score = points ÷ (applicable questions × maximum points). Questions marked not applicable are excluded.") }}
 {{ _("Maturity bands") }}: {% for b in r.scale %}{{ b.level|e }} {{ "%g"|format(b.from) }}–{{ "%g"|format(b.to) }}%{% if not loop.last %}, {% endif %}{% endfor %}.
 {{ _("Findings are raised for answers at level A (Immediate, 0–3 months) or B (High, 3–6 months).") }}
 {{ _("Gating questions cap the overall maturity level when answered at the trigger level.") }}</p>
</div>

<div id="footer-html">
 <table style="width:100%;font-family:Helvetica,Arial,sans-serif;font-size:8.5px;color:#5A6562;border-top:1px solid #D9E1E6;padding-top:4px">
  <tr>
   <td style="width:90px;vertical-align:middle"><img src="{{ brand.images.company_logo }}" style="height:22px;width:auto" alt="IRSAA"></td>
   <td style="vertical-align:middle">{{ brand.product_title }} · {{ brand.company }} · {{ brand.support_email }}<br>{{ _("Confidential") }} – {{ r.entity|e }} · {{ r.name|e }}</td>
   <td style="text-align:right;vertical-align:middle;white-space:nowrap">{{ _("Page") }} <span class="page"></span> {{ _("of") }} <span class="topage"></span></td>
  </tr>
 </table>
</div>
